<table border="1" cellpadding="1" cellspacing="1" style="width:500px;"><tbody><tr><td>1.</td><td><span class="math-tex">\(\begin{aligned} &amp; \vec{B}(x, t)=\left(9 \times 10^{-8}~\text T\right) \hat{j} \sin \left[1.5 \times 10^{-6} x-2 \times 10^{14} t\right] \end{aligned}\)</span></td></tr><tr><td>2.</td><td><span class="math-tex">\(\begin{aligned} &amp; \vec{B}(x, t)=\left(9 \times 10^{-8}~\text{T}\right) \hat{i} \sin \left[2 \pi\left(1.5 \times 10^{-8} x-2 \times 10^{14} t\right)\right] \end{aligned}\)</span></td></tr><tr><td>3.</td><td><span class="math-tex">\(\begin{aligned} &amp; \vec{B}(x, t)=\left(9 \times 10^{-8}~\text{T}\right) \hat{{k}} \sin \left[2 \pi\left(1.5 \times 10^{-6}{x}-2 \times 10^{14}{t}\right)\right] \end{aligned}\)</span></td></tr><tr><td>4.&nbsp;</td><td><span class="math-tex">\(\begin{aligned} &amp; \vec{B}(x, t)=\left(3 \times 10^{-8}~\text{T}\right) \hat{j} \sin \left[2 \pi\left(1.5 \times 10^{-8} x-2 \times 10^{14} t\right)\right] \end{aligned}\)</span></td></tr></tbody></table>
